floor_fn:
"""
    x = 5
          L      R
      1 3 4      10 10
   arr[i] <5 |   5 <= arr[i]


   x = 2
      L              R
      1              3 4 10 10
   arr[0..L] < 2 |   2 <= arr[R..N]
    """
def bisect_left(arr: Any, x: Any) -> object {
    N = len(arr);
    l = -1;
    r = N;
    while (r > (l + 1)) {
        m = (l + r) // 2;
        if (arr[m] < x) {
            l = m;
        } else {
            r = m;
        }
    }
    return l;
}

test_blocks:
test "t0" {
    assert (bisect_left(`list(), 1) == -1);;
}

test "t1" {
    assert (bisect_left(`list(range(10)), 5) == 4);;
}

test "t2" {
    assert (bisect_left(`list(range(10)), 3) == 2);;
}

test "t3" {
    assert (bisect_left(sorted([1, 3, 4]), 2) == 0);;
}

test "t4" {
    assert (bisect_left(sorted([1, 3, 4]), 5) == 2);;
}

test "t5" {
    assert (bisect_left([1, 3, 4], 5) == 2);;
}

test "t6" {
    assert (bisect_left([], 0) == -1);;
}

test "t7" {
    assert (bisect_left(`list("abracadabra"), "z") == 10);;
}

test "t8" {
    assert (bisect_left([], 3) == -1);;
}

test "t9" {
    assert (bisect_left([1, 3, 4], 0) == -1);;
}

test "t10" {
    assert (bisect_left(`list(range(10)), 10) == 9);;
}

test "t11" {
    assert (bisect_left(range(10), -1) == -1);;
}

test "t12" {
    assert (bisect_left(`list(range(10)), -1) == -1);;
}

test "t13" {
    assert (bisect_left([], 5) == -1);;
}

test "t14" {
    assert (bisect_left([1, 3, 4], 2) == 0);;
}

test "t15" {
    assert (bisect_left([], 2) == -1);;
}
